int main(){
  int n;
  long long k;
  cin >> n >> k;
  vector<long long> a(n);
  for (auto &x : a) cin >> x;
  sort(a.begin(), a.end());
  int mid = n / 2;
  auto cost = [&](long long x) {
    long long c = 0;
    for (int i = mid; i < n; i++)
      if (a[i] < x) c += x - a[i];
    return c;
  };
  long long lo = a[mid], hi = a[mid] + k;
  while (lo < hi) {
    long long m = lo + (hi - lo + 1) / 2;
    if (cost(m) <= k) lo = m;
    else hi = m - 1;
  }
  cout << lo << endl;
}

