    if (bal != 0) { cout << -1 << endl; continue; }
    string r(s.rbegin(), s.rend());
    if (regular(s) || regular(r)) {
      cout << 1 << endl;
      for (int i = 0; i < n; i++) cout << 1 << ' ';
      cout << endl;
