      else { p--; cout << (p >= 0 ? 1 : 2) << ' '; }
    }
    cout << endl;
  }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
  int t;
  cin >> t;
  while (t--) {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    vector<vector<int>> sp(LOG, vector<int>(n));
    sp[0] = a;
    for (int j = 1; j < LOG; j++)
      for (int i = 0; i + (1 << j) <= n; i++)
        sp[j][i] = sp[j - 1][i] & sp[j - 1][i + (1 << (j - 1))];
    auto query = [&](int l, int r) {
      int j = 31 - __builtin_clz(r - l + 1);
      return sp[j][l] & sp[j][r - (1 << j) + 1];
    };
    int q;
    cin >> q;
    vector<int> res;
    while (q--) {
      int l, k;
      cin >> l >> k;
      l--;
      if (a[l] < k) { res.push_back(-1); continue; }
      int lo = l, hi = n - 1;
      while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (query(l, mid) >= k) lo = mid;
        else hi = mid - 1;
      }
      res.push_back(lo + 1);
    }
    for (size_t i = 0; i < res.size(); i++)
      cout << res[i] << (i + 1 < res.size() ? ' ' : '\n');
  }
}

