    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (auto &x : a) cin >> x;
    for (auto &x : b) cin >> x;
    int A = 0, B = 0, plus = 0, minus = 0;
    for (int i = 0; i < n; i++) {
      int x = a[i], y = b[i];
      if (x == 1 && y == 1) plus++;
      else if (x == -1 && y == -1) minus++;
      else {
        if (x == 1) A++;
        if (y == 1) B++;
      }
    }
    for (int k = 0; k < plus; k++) {
      if (A < B) A++;
      else B++;
    }
    for (int k = 0; k < minus; k++) {
      if (A > B) A--;
      else B--;
    }
    cout << min(A, B) << endl;
  }
}

