  if (m < n - 1 || m > 2 * (n + 1)) {
    cout << -1 << endl;
    return 0;
  }
  vector<long long> g(n + 1, 0);
  long long left = m;
  for (long long i = 1; i <= n - 1; i++) {
    g[i] = 1;
    left--;
  }
  for (long long i = 0; i <= n; i++) {
    long long add = min(2 - g[i], left);
    g[i] += add;
    left -= add;
  }
  string s;
  for (long long i = 0; i <= n; i++) {
    s += string(g[i], '1');
    if (i < n) s += '0';
  }
  cout << s << endl;
}

