      cnt[x]++;
    }
    auto ok = [&](long long T) {
      long long taken = 0, slots = 0;
      for (int w = 1; w <= n; w++) {
        long long c = min(cnt[w], T);
        taken += c;
        slots += (T - c) / 2;
      }
      return (long long)m - taken <= slots;
    };
    long long lo = 1, hi = m;
    while (lo < hi) {
      long long mid = (lo + hi) / 2;
      if (ok(mid)) hi = mid;
      else lo = mid + 1;
    }
    cout << lo << endl;
  }
}

