    int cnt[26] = {0};
    for (char c : s) cnt[c - 'a']++;
    long long P = 0, O = 0;
    for (int c = 0; c < 26; c++) {
      P += cnt[c] / 2;
      O += cnt[c] % 2;
    }
    int ans = 1;
    for (long long L = 1; L * k <= n; L++) {
      long long h = L / 2;
      if (k * h > P) continue;
      if (L % 2 == 1 && O + 2 * (P - k * h) < k) continue;
      if (L > ans) ans = (int)L;
    }
    cout << ans << endl;
  }
}

